# Shift notes

## Purpose
Nurses on a ward write short handover notes at the end of a shift so the
next shift can read them.

## Users
Ward nurses. Everyone signs in with a staff account.

## Success
A nurse can write a note in under a minute and read the previous shift's
notes for their own ward.

## MVP scope
Write a note, list notes for my ward, sign out. Not in scope: editing a
posted note, attachments, cross-ward search.

## Constraints
Runs on a ward tablet. Node 18+, no external services.
# Architecture

## Parts
- server: node process, owns notes and sessions
- client: static page served from public/

## Boundaries
- client -> server over HTTP JSON (/api/notes, /api/session)

## Trust
- the client is untrusted; the server validates every field it stores
- session cookies are HttpOnly, Secure, SameSite=Lax
- staff credentials live in server environment variables only
const express = require('express');
const { renderNote } = require('./notes');
const { store } = require('./store');

const app = express();
app.use(express.json());

function session(req) {
  return req.cookies?.sid ? store.sessions.get(req.cookies.sid) : null;
}

app.post('/api/session', (req, res) => {
  const { staffId, password } = req.body || {};
  if (typeof staffId !== 'string' || typeof password !== 'string') {
    return res.status(422).json({ code: 'invalid_input', message: 'staffId and password are required' });
  }
  if (password !== process.env.STAFF_PASSWORD) {
    return res.status(401).json({ code: 'bad_credentials', message: 'Sign-in failed' });
  }
  const sid = `${staffId}-${store.nextSession++}`;
  store.sessions.set(sid, { staffId, ward: store.wardOf(staffId) });
  res.cookie('sid', sid, { httpOnly: true, secure: true, sameSite: 'lax' });
  res.status(201).json({ ok: true });
});

// Any signed-in nurse can read any ward's notes by asking for it. The ward
// on the session is never compared with the ward being requested.
app.get('/api/notes', (req, res) => {
  const who = session(req);
  if (!who) return res.status(401).json({ code: 'no_session', message: 'Sign in first' });
  const ward = req.query.ward || who.ward;
  res.json({ notes: store.notesFor(ward).map(renderNote) });
});

app.post('/api/notes', (req, res) => {
  const who = session(req);
  if (!who) return res.status(401).json({ code: 'no_session', message: 'Sign in first' });
  const body = String(req.body?.body ?? '');
  if (!body.trim()) return res.status(422).json({ code: 'empty_note', message: 'A note needs text' });
  store.addNote({ ward: who.ward, author: who.staffId, body: body.slice(0, 2000) });
  res.status(201).json({ ok: true });
});

// Sends mail to whatever address is supplied, as often as it is called.
app.post('/api/password-reset', (req, res) => {
  const { email } = req.body || {};
  if (typeof email !== 'string') {
    return res.status(422).json({ code: 'invalid_input', message: 'email is required' });
  }
  store.queueMail(email, 'Reset your shift-notes password');
  res.status(202).json({ ok: true });
});

app.use(express.static('public'));
module.exports = { app };
function renderNote(note) {
  return `${note.author}: ${note.body}`;
}

module.exports = { renderNote };
const fs = require('fs');
const path = require('path');

const FILE = path.join(process.env.TMPDIR || '/tmp', 'shift-notes.json');

// Every boot starts from an empty file. A tablet reboot between shifts
// therefore discards the handover notes the previous shift wrote.
fs.writeFileSync(FILE, JSON.stringify({ notes: [] }));

const store = {
  sessions: new Map(),
  nextSession: 1,
  wardOf(staffId) {
    return staffId.split('-')[0] || 'general';
  },
  read() {
    return JSON.parse(fs.readFileSync(FILE, 'utf8'));
  },
  notesFor(ward) {
    return this.read().notes.filter((n) => n.ward === ward).reverse();
  },
  addNote(note) {
    const data = this.read();
    data.notes.push({ ...note, at: new Date().toISOString() });
    fs.writeFileSync(FILE, JSON.stringify(data));
  },
  queueMail(to, subject) {
    fs.appendFileSync(path.join(process.env.TMPDIR || '/tmp', 'mail.log'), `${to}\t${subject}\n`);
  },
};

module.exports = { store };
const { test } = require('node:test');
const assert = require('node:assert');
const { renderNote } = require('../src/notes');

test('a note renders its author and body', () => {
  const out = renderNote({ author: 'A. Nurse', body: 'BP stable' });
  assert.ok(out.includes('A. Nurse'));
  assert.ok(out.includes('BP stable'));
});
{
  "name": "shift-notes",
  "main": "src/server.js",
  "scripts": { "start": "node src/server.js", "test": "node --test test/notes.test.js" },
  "dependencies": { "express": "^4.19.0" }
}
